// MIT. Partner operations through the selected complete original application.
// Native transport derives from the maintained Tasker client; its MIT notice is retained.
import {spawn} from 'node:child_process';
import {constants} from 'node:fs';
import {access, lstat, open, realpath} from 'node:fs/promises';
import {dirname, join, resolve} from 'node:path';
import {fileURLToPath} from 'node:url';

export const PARTNER_REQUEST_SCHEMA = 'stellar-forge.partner-operation-request.v1';
export const PARTNER_RESULT_SCHEMA = 'stellar-forge.partner-operation-result.v1';
export const PARTNER_SOURCE = dirname(fileURLToPath(import.meta.url));
export const PARTNER_MAX_REQUEST_BYTES = 2 * 1024 * 1024;
export const PARTNER_MAX_REPLY_BYTES = 16 * 1024 * 1024;
export const partnerError = (code, message) => Object.assign(new Error(message), {code});
export const plain = value => value !== null && typeof value === 'object' && !Array.isArray(value);
export function exact(value, fields, required = []) {
  if (!plain(value) || Object.keys(value).some(key => !fields.includes(key)) ||
      required.some(key => !Object.hasOwn(value, key)))
    throw partnerError('INVALID_PARAMS', 'Supply the declared fields and every required selection.');
}
export function selectedPath(value, base = process.cwd()) {
  if (typeof value !== 'string' || !value || /[\0\r\n]/.test(value))
    throw partnerError('PARTNER_PATH_INVALID', 'Select a complete original host path.');
  return resolve(base, value);
}
export function requestId(value) {
  if (typeof value !== 'string' || !/^[a-f0-9]{8}-[a-f0-9]{4}-4[a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$/.test(value))
    throw partnerError('INVALID_PARAMS', 'Retain one version-four request UUID for this complete operation.');
  return value;
}
export async function readPrivateJSON(path, maximum = 2 * 1024 * 1024) {
  path = selectedPath(path);
  if (await realpath(path) !== path) throw partnerError('PARTNER_PRIVATE_FILE', 'Use a canonical private original JSON file.');
  const handle = await open(path, constants.O_RDONLY | (constants.O_NOFOLLOW ?? 0) | (constants.O_NONBLOCK ?? 0));
  try {
    const stat = await handle.stat();
    if (!stat.isFile() || stat.size > maximum || process.platform !== 'win32' &&
        ((stat.mode & 0o077) || typeof process.getuid === 'function' && stat.uid !== process.getuid()))
      throw partnerError('PARTNER_PRIVATE_FILE', 'Use an owned private regular JSON file within its declared limit.');
    const bytes = await handle.readFile();
    if (bytes.length > maximum) throw partnerError('PARTNER_PRIVATE_FILE', 'The original JSON file exceeded its declared limit.');
    let value;
    try { value = JSON.parse(new TextDecoder('utf-8', {fatal: true}).decode(bytes)); }
    catch { throw partnerError('PARTNER_JSON_INVALID', 'Read the complete original UTF-8 JSON document.'); }
    return {path, bytes, value};
  } finally { await handle.close(); }
}
export async function canonicalDirectory(path, {missing = false, privateOnly = false} = {}) {
  path = selectedPath(path);
  let stat;
  try { stat = await lstat(path); }
  catch (error) {
    if (error.code !== 'ENOENT' || !missing) throw error;
    const parent = dirname(path);
    if (parent === path) throw error;
    await canonicalDirectory(parent, {privateOnly});
    return path;
  }
  if (!stat.isDirectory() || stat.isSymbolicLink() || await realpath(path) !== path ||
      privateOnly && process.platform !== 'win32' &&
      ((stat.mode & 0o077) || typeof process.getuid === 'function' && stat.uid !== process.getuid()))
    throw partnerError('PARTNER_DIRECTORY_INVALID', 'Select the canonical original directory with its required ownership and permissions.');
  return path;
}

const installedOperations = new Set(['installation.inspect', 'installation.adopt_source', 'installation.snapshot',
  'workspace.export', 'commands.describe', 'requests.get', 'workspace.state', 'workspace.record',
  'workspace.history', 'workspace.source', 'workspace.compare', 'workspace.stations']);
const mutations = new Set(['installation.prepare', 'installation.receive', 'installation.snapshot',
  'installation.adopt_source', 'workspace.export']);

/** This client has no queue, database, worker or automatic mutation retry of its own. */
export class PartnerInstallation {
  #selection; #active = new Set(); #closing = false; #closed;
  constructor(selection) {
    exact(selection, ['directory', 'sourceDirectory', 'python', 'binding', 'environment'], ['directory']);
    const directory = selectedPath(selection.directory);
    const sourceDirectory = selectedPath(selection.sourceDirectory ?? PARTNER_SOURCE);
    const python = selectedPath(selection.python ?? '/usr/bin/python3');
    if (selection.binding !== undefined) {
      exact(selection.binding, ['installation_id', 'source_identity'], ['installation_id', 'source_identity']);
      if (typeof selection.binding.installation_id !== 'string' ||
          !/^[a-f0-9-]{36}$/.test(selection.binding.installation_id) ||
          !/^[a-f0-9]{64}$/.test(selection.binding.source_identity ?? ''))
        throw partnerError('PARTNER_BINDING_INVALID', 'Keep the selected installation UUID and original source SHA256.');
    }
    this.#selection = {directory, sourceDirectory, python,
      ...(selection.binding ? {binding: {...selection.binding}} : {}),
      environment: selection.environment ?? process.env};
  }
  get selection() {
    const {environment, ...value} = this.#selection;
    return structuredClone(value);
  }
  get activeCalls() { return this.#active.size; }
  async #execute(operation, args, id) {
    const selected = this.#selection;
    await canonicalDirectory(selected.sourceDirectory);
    const script = join(selected.sourceDirectory, 'native', 'operations.py');
    const info = await lstat(script);
    if (!info.isFile() || info.isSymbolicLink() || await realpath(script) !== script)
      throw partnerError('PARTNER_SOURCE_INVALID', 'Select the complete native Partner operations source.');
    await access(selected.python, constants.X_OK);
    const body = {schema: PARTNER_REQUEST_SCHEMA, operation, arguments: args,
      ...(installedOperations.has(operation) ? {installation: selected.directory} : {}),
      ...(id === undefined ? {} : {request_id: id}),
      ...(installedOperations.has(operation) && selected.binding ? {binding: selected.binding} : {})};
    const encoded = Buffer.from(JSON.stringify(body) + '\n');
    if (encoded.length > PARTNER_MAX_REQUEST_BYTES)
      throw partnerError('INVALID_PARAMS', 'The complete Partner request exceeds two MiB.');
    return new Promise((accept, reject) => {
      let child, bytes = 0, failure = null;
      const chunks = [];
      try { child = spawn(selected.python, ['-B', script], {cwd: selected.sourceDirectory,
        env: selected.environment, shell: false, stdio: ['pipe', 'pipe', 'pipe']}); }
      catch { reject(partnerError('PARTNER_LAUNCH_FAILED', 'The selected original Python process could not start.')); return; }
      child.stdout.on('data', chunk => {
        bytes += chunk.length;
        if (bytes > PARTNER_MAX_REPLY_BYTES) {
          failure ??= partnerError('PARTNER_REPLY_LIMIT', 'The native reply exceeds sixteen MiB. Read the same lifecycle request or export the complete original workspace.');
          child.kill('SIGTERM');
        } else chunks.push(chunk);
      });
      // Original stderr can contain host paths or provider output. Keep it out of model replies.
      child.stderr.on('data', () => {});
      child.stdin.on('error', () => {});
      child.once('error', () => { failure ??= partnerError('PARTNER_LAUNCH_FAILED', 'The selected original Python process could not start.'); });
      child.once('close', (code, signal) => {
        if (failure) { reject(failure); return; }
        let value;
        try { value = JSON.parse(new TextDecoder('utf-8', {fatal: true}).decode(Buffer.concat(chunks, bytes))); }
        catch {
          reject(partnerError('PARTNER_REPLY_INVALID',
            'The original process did not return complete UTF-8 JSON (exit ' + code + ', signal ' + (signal ?? 'none') +
            '). Reconcile the same request ID before another mutation.'));
          return;
        }
        if (!plain(value) || value.schema !== PARTNER_RESULT_SCHEMA || value.operation !== operation ||
            typeof value.ok !== 'boolean' || (id !== undefined && value.request_id !== id)) {
          reject(partnerError('PARTNER_REPLY_CHANGED', 'The native response does not identify this original operation and request.'));
          return;
        }
        if (!value.ok) {
          const errorCode = /^[A-Za-z][A-Za-z0-9_]{0,127}$/.test(value.error?.code ?? '') ? value.error.code : 'PARTNER_OPERATION_FAILED';
          const message = typeof value.error?.message === 'string' ? value.error.message.slice(0, 2000) : 'The original Partner operation failed.';
          reject(partnerError(errorCode, message)); return;
        }
        if (code !== 0 || signal) {
          reject(partnerError('PARTNER_PROCESS_EXIT', 'The original process exited after its reply. Reconcile this retained request ID before retrying.'));
          return;
        }
        accept(value);
      });
      child.stdin.end(encoded);
    });
  }
  call(operation, args = {}, id) {
    if (this.#closing) return Promise.reject(partnerError('PARTNER_CLOSING', 'The Partner client is draining its original calls.'));
    if ((!installedOperations.has(operation) && !['installation.prepare', 'installation.receive', 'source.inspect'].includes(operation)) || !plain(args))
      return Promise.reject(partnerError('INVALID_PARAMS', 'Select a declared Partner operation and complete JSON arguments.'));
    if (mutations.has(operation)) requestId(id);
    else if (id !== undefined) requestId(id);
    const input = structuredClone(args);
    const pending = this.#execute(operation, input, id);
    this.#active.add(pending);
    pending.finally(() => this.#active.delete(pending)).catch(() => {});
    return pending;
  }
  inspect() { return this.call('installation.inspect'); }
  source(input) { return this.call('source.inspect', input); }
  prepare(input, id) { return this.call('installation.prepare', {...input, directory: this.#selection.directory}, id); }
  receive(input, id) { return this.call('installation.receive', {...input, directory: this.#selection.directory}, id); }
  snapshot(output, id) { return this.call('installation.snapshot', {output}, id); }
  adoptSource(input, id) { return this.call('installation.adopt_source', input, id); }
  state() { return this.call('workspace.state'); }
  record(kind, id) { return this.call('workspace.record', {kind, id}); }
  history(kind, id) { return this.call('workspace.history', {kind, id}); }
  export(kind, output, id) { return this.call('workspace.export', {kind, output}, id); }
  request(request_id, origin_installation_id) {
    return this.call('requests.get', {request_id, ...(origin_installation_id === undefined ? {} : {origin_installation_id})});
  }
  close() {
    return this.#closed ??= (async () => { this.#closing = true; await Promise.allSettled([...this.#active]); })();
  }
}

"""Complete original mobility and education runtime source selection."""
from __future__ import annotations
import contextlib,importlib,os,re,subprocess,sys
from pathlib import Path
from files import *
SOURCE_SCHEMA="stellar-forge.partner-product-source.v1"
EDITION_SCHEMA="stellar-forge.partner-source-edition.v1"
BRIDGE_FILES=("files.py","source.py","manage.py","operations.py","launch.py")
REQUIRED=("workbench/__init__.py","workbench/core.py","workbench/app.py","workbench/mobility.py","workbench/education.py","run.py","static/app.js","static/index.html","static/style.css","README.md","LICENSE")
def manifest_value(value):
    exact(value,("schema","title","product","files","provenance"),("schema","title","product","files"))
    need(value["schema"]==SOURCE_SCHEMA and value["product"] in ("mobility","education"),"source_schema","Select a complete original mobility or education source manifest.")
    need(isinstance(value["title"],str) and 1<=len(value["title"])<=240,"source_title","Give the original application a title.")
    rows=value["files"];need(isinstance(rows,list) and 1<=len(rows)<=10000,"source_members","Select every complete runtime member.")
    paths=set();total=0
    for row in rows:
        exact(row,("path","bytes","sha256"),("path","bytes","sha256"))
        path=relative(row["path"])
        need(path not in paths and (path.startswith(("workbench/","static/")) or path in ("run.py","README.md","LICENSE")) and "__pycache__" not in Path(path).parts and (path=="LICENSE" or Path(path).suffix in (".py",".js",".css",".html",".md",".json",".txt")),"source_member","Select the complete runtime members supported by the original archive; keep commercial and receiving files in their original case.")
        need(isinstance(row["bytes"],int) and not isinstance(row["bytes"],bool) and 0<=row["bytes"]<=MAX_SOURCE_FILE and re.fullmatch(r"[a-f0-9]{64}",str(row["sha256"])),"source_member","Retain complete file identities.")
        paths.add(path);total+=row["bytes"]
    need(set(REQUIRED)<=paths and total<=MAX_SOURCE_BYTES,"source_incomplete","Include the original runtime, static application, guide and LICENSE.")
    return value
def selected_manifest(path):
    raw=read(path,8*1024*1024);return manifest_value(decode(raw)),{"path":str(absolute(path)),"bytes":len(raw),"sha256":digest(raw)}
def bridge_manifest(root):
    return [{"path":name,**{k:v for k,v in file_identity(absolute(root)/name).items() if k in ("bytes","sha256")}} for name in BRIDGE_FILES]
def source_identity(manifest,bridge):
    return digest(encoded({"source":manifest,"bridge":bridge}))
def check_source(root,manifest):
    root=directory(root)
    for row in manifest["files"]:
        actual=file_identity(root/row["path"],MAX_SOURCE_FILE)
        need(actual["bytes"]==row["bytes"] and actual["sha256"]==row["sha256"],"source_changed","Original source member changed: "+row["path"])
    return root
def materialize_edition(root,source_root,manifest,bridge_root,bridge):
    manifest_value(manifest);check_source(source_root,manifest)
    need(bridge==bridge_manifest(bridge_root),"bridge_changed","Select the complete original native bridge.")
    identity=source_identity(manifest,bridge);edition=directory(absolute(root)/"editions"/identity,create=True,private=True)
    for rows,src,dst in ((manifest["files"],absolute(source_root),edition/"source"),(bridge,absolute(bridge_root),edition/"bridge")):
        for row in rows:copy_file(src/row["path"],dst/row["path"],row)
    once(edition/"SOURCE.json",encoded(manifest));once(edition/"BRIDGE.json",encoded(bridge))
    value={"schema":EDITION_SCHEMA,"source_identity":identity,"product_source_identity":digest(encoded(manifest)),"directory":str(edition),"source":str(edition/"source"),"bridge":str(edition/"bridge")}
    once(edition/"EDITION.json",encoded(value));return value
def read_edition(root,identity,verify=True):
    need(isinstance(identity,str) and re.fullmatch(r"[a-f0-9]{64}",identity),"source_identity","Select an original source edition.")
    path=directory(absolute(root)/"editions"/identity);value=read_json(path/"EDITION.json")
    manifest=manifest_value(read_json(path/"SOURCE.json"));bridge=read_json(path/"BRIDGE.json")
    expected={"schema":EDITION_SCHEMA,"source_identity":identity,"product_source_identity":digest(encoded(manifest)),"directory":str(path),"source":str(path/"source"),"bridge":str(path/"bridge")}
    need(value==expected and [r.get("path") for r in bridge]==list(BRIDGE_FILES) and source_identity(manifest,bridge)==identity,"source_edition_changed","The complete source edition binding changed.")
    if verify:
        check_source(path/"source",manifest);need(bridge_manifest(path/"bridge")==bridge,"bridge_changed","The installed native bridge changed.")
    return value,manifest
def python_selection(value):
    requested=absolute(value);resolved=requested.resolve(strict=True)
    need(resolved.is_file() and os.access(resolved,os.X_OK),"python_unavailable","Select an installed Python executable.")
    result=subprocess.run([str(resolved),"-B","-c","import json,pathlib,sqlite3,sys;print(json.dumps({'path':str(pathlib.Path(sys.executable).resolve()),'version':list(sys.version_info[:3]),'sqlite':sqlite3.sqlite_version}))"],capture_output=True,timeout=30)
    need(result.returncode==0,"python_unavailable","The selected Python could not load its standard SQLite runtime.")
    selected=decode(result.stdout);need(selected["path"]==str(resolved) and selected["version"][:2]>=[3,11],"python_version","Select Python 3.11 or later.")
    return selected
@contextlib.contextmanager
def application(root,selected):
    edition,manifest=read_edition(root,selected["source_identity"]);source=Path(edition["source"]);before=list(sys.path)
    names=[name for name in sys.modules if name=="workbench" or name.startswith("workbench.")]
    saved={name:sys.modules.pop(name) for name in names}
    try:
        sys.path.insert(0,str(source));importlib.invalidate_caches()
        core=importlib.import_module("workbench.core");app=importlib.import_module("workbench.app")
        for module in (core,app):
            need(Path(module.__file__).resolve().is_relative_to(source/"workbench"),"original_module_changed","The original module resolved outside its selected complete source.")
        yield {"edition":edition,"manifest":manifest,"source":source,"core":core,"app":app,"Workspace":core.Workspace,"restore":core.restore}
    finally:
        for name in list(sys.modules):
            if name=="workbench" or name.startswith("workbench."):sys.modules.pop(name,None)
        sys.modules.update(saved);sys.path[:]=before;importlib.invalidate_caches()

"""Whole source-selected installations; original workbench owns business state."""
from __future__ import annotations
from datetime import datetime,timezone
import os,re,shutil,sys,uuid,zipfile
from pathlib import Path
from files import *
from source import *
INSTALL_SCHEMA="stellar-forge.partner-installation.v1"
SNAPSHOT_SCHEMA="stellar-forge.partner-installation-archive.v1"
SOURCE_ROOT=Path(__file__).resolve().parent
def now():return datetime.now(timezone.utc).isoformat()
def input_file(path):return {k:v for k,v in file_identity(path).items() if k in ("path","bytes","sha256")}
def installation(path,verify=True):
    root=directory(path,private=True);value=read_json(root/"installation.json")
    need(value.get("schema")==INSTALL_SCHEMA and value.get("directory")==str(root) and re.fullmatch(r"[a-f0-9-]{36}",str(value.get("installation_id",""))),"installation_changed","Select the complete original installation.")
    workspace=absolute(value["workspace"]);need((root/"workspaces") in workspace.parents,"workspace_changed","Keep the original workspace inside its installation.")
    need((workspace/"workspace.sqlite3").is_file(),"workspace_missing","The original workspace database is absent.")
    _,manifest=read_edition(root,value["source_identity"],verify)
    need(value["product"]==manifest["product"],"product_changed","The selected source belongs to another product.")
    return value
def summary(value):
    root=Path(value["directory"]);edition,manifest=read_edition(root,value["source_identity"],False);info=root.stat()
    return {"installation_id":value["installation_id"],"operation_id":value["operation_id"],"source_identity":value["source_identity"],"product_source_identity":edition["product_source_identity"],"product":value["product"],"title":manifest["title"],"workspace_id":value["workspace_id"],"python":value["python"],"paths":{"directory":str(root),"source":edition["source"],"application":edition["source"],"workspace":value["workspace"],"database":str(Path(value["workspace"])/"workspace.sqlite3"),"bridge":edition["bridge"]},"binding":{"directory":str(root),"device":str(info.st_dev),"inode":str(info.st_ino)},"received_from":value.get("received_from")}
def check_binding(value,binding):
    if binding is None:return
    exact(binding,("installation_id","source_identity"),("installation_id","source_identity"))
    need(all(value[k]==binding[k] for k in binding),"installation_changed","Inspect the selected original installation and source before operating it.")
def journal(root,op,kind,request):
    path=directory(Path(root)/"operations"/identifier(op),create=True,private=True)
    once(path/"REQUEST.json",encoded({"schema":"stellar-forge.partner-lifecycle-request.v1","operation_id":op,"kind":kind,"request":request}))
    return path,read_json(path/"RESULT.json") if (path/"RESULT.json").exists() else None
def finish(path,result):
    once(path/"RESULT.json",encoded(result));return result
def replay(root,op,kind,selection):
    path=root/"operations"/identifier(op)
    if not (path/"REQUEST.json").exists():return None
    record=read_json(path/"REQUEST.json");request=record["request"]
    need(record["kind"]==kind and request["selection"]==selection,"operation_conflict","Retain the exact original operation and selected inputs.")
    result=read_json(path/"RESULT.json") if (path/"RESULT.json").exists() else None
    if not result and (path/"COMMIT.json").exists():
        committed=read_json(path/"COMMIT.json");target=committed["installation"]
        need(target["directory"]==str(root),"installation_changed","The retained commit identifies another directory.")
        read_edition(root,target["source_identity"])
        with application(root,target) as ctx:
            ws=ctx["Workspace"](target["workspace"],target["product"]);ws.validate()
            need(ws.meta["id"]==target["workspace_id"],"workspace_changed","The retained committed workspace changed.")
        if (root/"installation.json").exists():
            current=installation(root)
            before=read_json(path/"BEFORE.json") if (path/"BEFORE.json").exists() else None
            need(current==target or kind=="adopt_source" and current==before,"installation_changed","The interrupted installation marker differs from its retained transition.")
        save(root/"installation.json",target)
        result=finish(path,committed)
    if result:
        if result.get("installation"):
            current=installation(root);need(current["installation_id"]==result["installation"]["installation_id"],"installation_changed","The directory now belongs to another installation.")
            read_edition(root,result["installation"]["source_identity"])
        for key in ("source_manifest","workspace_archive","archive"):
            value=request.get(key)
            if value and Path(value["path"]).exists():
                actual=input_file(value["path"]);need(actual==value,"operation_input_changed","A surviving original input changed: "+key)
        if request.get("source_identity") and Path(selection.get("source_root","/nonexistent")).exists():
            _,manifest=read_edition(root,request["source_identity"]);check_source(selection["source_root"],manifest)
        if request.get("archive"):
            original=root/"inputs"/"Original_Installation.zip"
            actual=input_file(original);need(actual["bytes"]==request["archive"]["bytes"] and actual["sha256"]==request["archive"]["sha256"],"original_archive_changed","The retained original installation archive changed.")
        if result.get("archive"):
            actual=input_file(result["archive"]["path"]);need(actual==result["archive"],"archive_changed","The completed archive changed.")
        return {**result,"replayed":True}
    return None
def commit(root,path,result):
    once(path/"COMMIT.json",encoded(result));save(root/"installation.json",result["installation"]);return finish(path,result)
def restore_original(root,path,selected,archive):
    attempts=directory(path/"attempts",create=True,private=True)
    for attempt in sorted(attempts.iterdir()):
        if (attempt/"RESTORED.json").exists():
            value=read_json(attempt/"RESTORED.json")
            with application(root,selected) as ctx:
                ws=ctx["Workspace"](value["workspace"],ctx["manifest"]["product"]);ws.validate()
                need(ws.meta==value["metadata"],"workspace_changed","Retained workspace identity changed.")
            return value
    attempt=directory(attempts/str(uuid.uuid4()),create=True,private=True);outer=root/"workspaces"/str(uuid.uuid4())
    directory(outer.parent,create=True,private=True)
    with application(root,selected) as ctx:
        if archive:
            ctx["restore"](archive,outer);workspace=outer/"workspace"
        else:
            directory(outer,create=True,private=True);workspace=outer/"workspace";ctx["Workspace"](workspace,ctx["manifest"]["product"],True)
        ws=ctx["Workspace"](workspace,ctx["manifest"]["product"]);ws.validate()
        value={"workspace":str(workspace),"metadata":ws.meta,"completed_at":now(),"archive":input_file(archive) if archive else None}
    save(attempt/"RESTORED.json",value);return value
def prepare(*,source_root,source_manifest,directory_path,python,operation_id,workspace_archive=None):
    root=directory(directory_path,create=True,private=True)
    selection={"source_root":str(absolute(source_root)),"source_manifest":str(absolute(source_manifest)),"python":str(absolute(python)),"workspace_archive":str(absolute(workspace_archive)) if workspace_archive else None}
    with locked(root/"installation.lock"):
        prior=replay(root,operation_id,"prepare",selection)
        if prior:return prior
        manifest,identity=selected_manifest(source_manifest);check_source(source_root,manifest)
        bridge=bridge_manifest(SOURCE_ROOT);sid=source_identity(manifest,bridge);chosen_python=python_selection(python)
        request={"selection":selection,"source_identity":sid,"source_manifest":identity,"workspace_archive":input_file(workspace_archive) if workspace_archive else None}
        path,_=journal(root,operation_id,"prepare",request)
        need(not (root/"installation.json").exists(),"installation_exists","Select an empty installation or receive its existing named operation.")
        once(root/"CREATION.json",encoded({"operation_id":operation_id,"kind":"prepare","request_sha256":digest(encoded(request))}))
        materialize_edition(root,source_root,manifest,SOURCE_ROOT,bridge)
        archive=None
        if workspace_archive:
            archive=root/"inputs"/"Original_Workspace.zip";copy_file(workspace_archive,archive,request["workspace_archive"])
        restored=restore_original(root,path,{"source_identity":sid},archive)
        value={"schema":INSTALL_SCHEMA,"installation_id":str(uuid.uuid4()),"operation_id":operation_id,"created_at":now(),"directory":str(root),"source_identity":sid,"source_history":[sid],"product":manifest["product"],"workspace_id":restored["metadata"]["id"],"workspace":restored["workspace"],"python":chosen_python,"received_from":None}
        return commit(root,path,{"installation":value,"restored":restored,"replayed":False})
def inspect(root):
    value=installation(root)
    with application(root,value) as ctx:
        ws=ctx["Workspace"](value["workspace"],value["product"]);ws.validate()
