        rows=inventory(stage);identity=write_zip(output,stage,rows,{"schema":SNAPSHOT_SCHEMA,"operation_id":op,"installation_id":value["installation_id"],"workspace_id":value["workspace_id"],"product":value["product"],"source_identity":value["source_identity"]})
        return finish(path,{"archive":{k:identity[k] for k in ("path","bytes","sha256")},"installation_id":value["installation_id"],"workspace_id":value["workspace_id"],"replayed":False})
def receive(*,archive_path,directory_path,python,operation_id):
    root=directory(directory_path,create=True,private=True);selection={"archive":str(absolute(archive_path)),"python":str(absolute(python))}
    with locked(root/"installation.lock"):
        prior=replay(root,operation_id,"receive",selection)
        if prior:return prior
        identity=input_file(archive_path);index=verify_zip(archive_path,schema=SNAPSHOT_SCHEMA);chosen_python=python_selection(python)
        request={"selection":selection,"archive":identity};path,_=journal(root,operation_id,"receive",request)
        need(not (root/"installation.json").exists(),"installation_exists","Select a new independent receiving directory.")
        once(root/"CREATION.json",encoded({"operation_id":operation_id,"kind":"receive","request_sha256":digest(encoded(request))}))
        retained=root/"inputs"/"Original_Installation.zip";copy_file(archive_path,retained,identity)
        staged=directory(path/"input",create=True,private=True);extract_zip(retained,staged)
        old=read_json(staged/"INSTALLATION.json")
        need(old["schema"]==INSTALL_SCHEMA and old["installation_id"]==index["installation_id"] and old["workspace_id"]==index["workspace_id"] and old["product"]==index["product"] and old["source_identity"]==index["source_identity"],"archive_binding","The complete original installation binding differs.")
        for sid in old["source_history"]:
            selected=staged/"editions"/sid;manifest=manifest_value(read_json(selected/"SOURCE.json"));bridge=read_json(selected/"BRIDGE.json")
            need(source_identity(manifest,bridge)==sid,"source_changed","The original source edition identity changed.")
            materialize_edition(root,selected/"source",manifest,selected/"bridge",bridge)
        lineage=directory(root/"lineage",create=True,private=True)
        if (staged/"lineage").exists():
            for row in inventory(staged/"lineage"):copy_file(staged/"lineage"/row["path"],lineage/row["path"],row)
        oldline=directory(lineage/old["installation_id"],create=True,private=True)
        once(oldline/"INSTALLATION.json",encoded(old))
        if (staged/"operations").exists():
            for row in inventory(staged/"operations"):copy_file(staged/"operations"/row["path"],oldline/"operations"/row["path"],row)
        restored=restore_original(root,path,{"source_identity":old["source_identity"]},staged/"Original_Workspace.zip")
        need(restored["metadata"]["id"]==old["workspace_id"] and restored["metadata"]["product"]==old["product"],"workspace_changed","The complete restored workspace differs from its original selection.")
        value={**old,"installation_id":str(uuid.uuid4()),"operation_id":operation_id,"created_at":now(),"directory":str(root),"workspace":restored["workspace"],"python":chosen_python,"received_from":{"installation_id":old["installation_id"],"archive_sha256":identity["sha256"],"operation_id":index["operation_id"]}}
        return commit(root,path,{"installation":value,"restored":restored,"original_archive":identity,"replayed":False})
def adopt_source(root,source_root,source_manifest,op,binding=None):
    root=directory(root,private=True);selection={"source_root":str(absolute(source_root)),"source_manifest":str(absolute(source_manifest)),"binding":binding}
    with locked(root/"installation.lock"),locked(root/"services"/"operator.lock"):
        prior=replay(root,op,"adopt_source",selection)
        if prior:return prior
        value=installation(root);check_binding(value,binding);manifest,identity=selected_manifest(source_manifest);need(manifest["product"]==value["product"],"product_changed","An existing workspace keeps its original product.")
        bridge=bridge_manifest(SOURCE_ROOT);sid=source_identity(manifest,bridge);request={"selection":selection,"source_manifest":identity,"source_identity":sid}
        path,_=journal(root,op,"adopt_source",request);once(path/"BEFORE.json",encoded(value));materialize_edition(root,source_root,manifest,SOURCE_ROOT,bridge)
        selected={**value,"source_identity":sid,"source_history":value["source_history"]+([] if sid in value["source_history"] else [sid])}
        with application(root,selected) as ctx:
            ws=ctx["Workspace"](selected["workspace"],selected["product"]);ws.validate();need(ws.meta["id"]==value["workspace_id"],"workspace_changed","The source successor changed the original workspace identity.")
        return commit(root,path,{"installation":selected,"previous_source_identity":value["source_identity"],"replayed":False})
def request_record(root,request_id,origin_installation_id=None):
    value=installation(root);path=Path(root)
    if origin_installation_id:path=path/"lineage"/identifier(origin_installation_id)
    path=path/"operations"/identifier(request_id)
    return {"request":read_json(path/"REQUEST.json"),"result":read_json(path/"RESULT.json") if (path/"RESULT.json").exists() else None,"installation_id":origin_installation_id or value["installation_id"]}
def describe_commands(root,args):
    value=installation(root);info=summary(value);ready=absolute(args["ready_file"]);port=args.get("port",0)
    need(isinstance(port,int) and not isinstance(port,bool) and 0<=port<=65535,"port_invalid","Choose an available loopback port.")
    directory(ready.parent,create=True,private=True);need(not ready.exists(),"ready_file_exists","Select a new private service-ready file.")
    script=Path(info["paths"]["bridge"])/"launch.py";argv=[value["python"]["path"],"-B",str(script),"--directory",str(root),"--installation-id",value["installation_id"],"--source-identity",value["source_identity"],"--ready-file",str(ready),"--port",str(port)]
    return {"commands":[{"role":"operator","executable":argv[0],"argv":argv,"cwd":info["paths"]["application"],"script":str(script),"script_sha256":file_identity(script)["sha256"],"ready_file":str(ready),"workspace_id":value["workspace_id"],"product":value["product"]}]}

#!/usr/bin/env python3
"""JSON operations for the complete selected partner installation."""
from __future__ import annotations
import argparse
import math
import os
from pathlib import Path
import subprocess
import sys
import zipfile
from files import WorkbenchError, absolute, decode, digest, encoded, exact, identifier, need, read
import manage
from source import selected_manifest, check_source

REQUEST = "stellar-forge.partner-operation-request.v1"
RESULT = "stellar-forge.partner-operation-result.v1"
CURRENT_REQUEST = {}
MAX_REQUEST = 2 * 1024 * 1024
READS = {"workspace.state": (), "workspace.record": ("kind","id"), "workspace.history": ("kind","id"),
         "workspace.source": ("id",), "workspace.compare": ("ids",), "workspace.stations": ("id",)}
FIELDS = {
    "source.inspect": (("source_root", "source_manifest"), ("source_root", "source_manifest")),
    "installation.prepare": (("source_root", "source_manifest", "directory", "python", "workspace_archive"),
                             ("source_root", "source_manifest", "directory")),
    "installation.inspect": ((), ()),
    "installation.receive": (("archive_path", "directory", "python"), ("archive_path", "directory")),
    "installation.snapshot": (("output",), ("output",)),
    "installation.adopt_source": (("source_root", "source_manifest"), ("source_root", "source_manifest")),
    "workspace.export": (("kind", "output"), ("kind", "output")),
    "commands.describe": (("ready_file", "port"), ("ready_file",)),
    "requests.get": (("request_id", "origin_installation_id"), ("request_id",)),
}
MUTATIONS = {"installation.prepare", "installation.receive", "installation.snapshot", "installation.adopt_source",
             "workspace.export"}


def safe_numbers(value):
    if isinstance(value, bool) or value is None or isinstance(value, str):
        return value
    if isinstance(value, int):
        return str(value) if abs(value) > 9007199254740991 else value
    if isinstance(value, float):
        need(math.isfinite(value), "invalid_native_number", "The original result contains a non-finite number.")
        return value
    if isinstance(value, list):
        return [safe_numbers(item) for item in value]
    if isinstance(value, dict):
        return {key: safe_numbers(item) for key, item in value.items()}
    return value


def run(request):
    exact(request, ("schema", "operation", "arguments", "installation", "request_id", "binding"),
          ("schema", "operation"))
    need(request["schema"] == REQUEST, "request_schema", "Use the partner operation request schema.")
    operation = request["operation"]
    args = request.get("arguments", {})
    if operation in READS:
        exact(args, READS[operation], READS[operation])
    else:
        need(operation in FIELDS, "unknown_operation", "Select a declared partner product operation.")
        exact(args, *FIELDS[operation])
    request_id = request.get("request_id")
    if operation in MUTATIONS:
        identifier(request_id)
    elif request_id is not None:
        identifier(request_id)
    root = request.get("installation")
    if operation not in ("source.inspect", "installation.prepare", "installation.receive"):
        need(root is not None, "installation_required", "Select the original installed partner directory.")
    binding = request.get("binding")
    if root is not None and operation != "installation.adopt_source":
        selected = manage.installation(root)
        manage.check_binding(selected, binding)
    result = None; value = None
    if operation == "source.inspect":
        manifest, original = selected_manifest(args["source_manifest"])
        check_source(args["source_root"], manifest)
        result = {"source": manifest, "selection": original, "files": len(manifest["files"]),
                  "bytes": sum(x["bytes"] for x in manifest["files"])}
    elif operation == "installation.prepare":
        result = manage.prepare(source_root=args["source_root"], source_manifest=args["source_manifest"],
                                directory_path=args["directory"], python=args.get("python", str(Path(sys.executable).resolve())),
                                operation_id=request_id, workspace_archive=args.get("workspace_archive"))
        value = result["installation"]
    elif operation == "installation.receive":
        result = manage.receive(archive_path=args["archive_path"], directory_path=args["directory"],
                                python=args.get("python", str(Path(sys.executable).resolve())), operation_id=request_id)
        value = result["installation"]
    elif operation == "installation.inspect":
        result = manage.inspect(root); value = result["installation"]
    elif operation == "installation.snapshot":
        result = manage.snapshot(root, args["output"], request_id)
    elif operation == "installation.adopt_source":
        result = manage.adopt_source(root, args["source_root"], args["source_manifest"], request_id, binding)
        value = result["installation"]
    elif operation == "workspace.export":
        result = manage.export_original(root, args["kind"], args["output"], request_id)
    elif operation == "commands.describe":
        result = manage.describe_commands(root, args)
    elif operation == "requests.get":
        result = manage.request_record(root, args["request_id"], args.get("origin_installation_id"))
    else:
        result = manage.read_business(root, operation, args)
    if value is None and root is not None:
        value = manage.installation(root, verify=False)
    return {"schema": RESULT, "ok": True, "operation": operation, "request_id": request_id,
            "installation": manage.summary(value) if value else None, "result": result,
            "replayed": bool(isinstance(result, dict) and result.get("replayed")),
            "adapter_sha256": digest(Path(__file__).read_bytes())}


def main():
    global CURRENT_REQUEST
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--request", default="-")
    options = parser.parse_args()
    raw = sys.stdin.buffer.read(MAX_REQUEST + 1) if options.request == "-" else read(absolute(options.request), MAX_REQUEST)
    need(len(raw) <= MAX_REQUEST, "request_size", "The complete native JSON request exceeds two MiB.")
    request = decode(raw)
    need(isinstance(request, dict), "request_object", "The complete request must be a JSON object.")
    CURRENT_REQUEST = request
    need(isinstance(request.get("arguments", {}), dict), "arguments_object", "Operation arguments must be a JSON object.")
    # The selected original interpreter runs the original model and standard-library dependencies.
    # Forward one unchanged complete request if the adapter was opened by another
    # supported Python; never reinterpret source fields as shell commands.
    target = request.get("arguments", {}).get("python") if isinstance(request, dict) else None
    if target is None and isinstance(request, dict) and request.get("installation"):
        try:
            target = manage.installation(request["installation"], verify=False)["python"]["path"]
        except (FileNotFoundError, WorkbenchError):
            pass
    if target:
        resolved = absolute(target).resolve(strict=True)
        if resolved != Path(sys.executable).resolve():
            result = subprocess.run([str(resolved), "-B", str(Path(__file__).resolve())], input=raw)
            return result.returncode
    answer = run(request)
    print(encoded(safe_numbers(answer)).decode(), end="", flush=True)
    return 0


if __name__ == "__main__":
    try:
        raise SystemExit(main())
    except (WorkbenchError, ValueError, KeyError, TypeError, OSError, EOFError, ImportError, zipfile.BadZipFile, subprocess.SubprocessError) as error:
        # Source paths and original error descriptions are useful local detail.
        # Request values, process environments and native account secrets are not echoed.
        code = getattr(error, "code", "original_partner_operation_failed")
        reply = {"schema": RESULT, "ok": False, "operation": CURRENT_REQUEST.get("operation"),
                 "request_id": CURRENT_REQUEST.get("request_id"), "error": {"code": str(code), "message": str(error)[:2000]},
                 "adapter_sha256": digest(Path(__file__).read_bytes())}
        print(encoded(reply).decode(), end="", flush=True)
        raise SystemExit(2)

#!/usr/bin/env python3
"""Run the original workbench server in the existing Applications child."""
from __future__ import annotations
import argparse,io,json,os,signal,sys,uuid
from pathlib import Path
from urllib.parse import urlsplit
from files import *
from source import application,read_edition
import manage
PROCESS_SCHEMA="stellar-forge.partner-process.v1"
class OriginalAnnouncement(io.TextIOBase):
    def __init__(self,stream,identity,metadata,ready,port):
        self.stream=stream;self.identity=identity;self.metadata=metadata;self.ready=ready;self.port=port;self.pending="";self.received=False
    @property
    def encoding(self):return "utf-8"
    def writable(self):return True
    def write(self,text):
        count=len(text);self.pending+=text
        while "\n" in self.pending:
            line,self.pending=self.pending.split("\n",1)
            try:value=json.loads(line)
            except (ValueError,TypeError):value=None
            if not self.received and isinstance(value,dict) and "url" in value:
                need(value.get("workspace")==self.metadata,"original_workspace_changed","The server announced a different original workspace.")
                parsed=urlsplit(value["url"]);need(parsed.scheme=="http" and parsed.hostname=="127.0.0.1" and parsed.port and parsed.path in ("","/") and not parsed.query and not parsed.fragment and not parsed.username and not parsed.password and (not self.port or parsed.port==self.port),"original_service_url","The original server announced an invalid local URL.")
                result={**self.identity,"url":value["url"],"origin":"http://127.0.0.1:"+str(parsed.port)}
                once(self.ready,encoded(result));self.stream.write(encoded({k:v for k,v in result.items() if k!="url"}).decode());self.stream.flush();self.received=True
            else:self.stream.write(line+"\n")
        return count
    def flush(self):self.stream.flush()
def main():
    p=argparse.ArgumentParser(description=__doc__)
    for name in ("directory","installation-id","source-identity","ready-file"):p.add_argument("--"+name,required=True)
    p.add_argument("--port",type=int,default=0);a=p.parse_args()
    need(0<=a.port<=65535,"port_invalid","Select a loopback port.")
    root=directory(a.directory,private=True);ready=absolute(a.ready_file);directory(ready.parent,private=True)
    need(not ready.exists(),"ready_file_exists","Use a new original ready file.")
    with locked(root/"services"/"operator.lock") as fd:
        os.set_inheritable(fd,True)
        value=manage.installation(root);manage.check_binding(value,{"installation_id":a.installation_id,"source_identity":a.source_identity})
        need(Path(sys.executable).resolve()==Path(value["python"]["path"]),"interpreter_changed","Use the selected original Python.")
        edition,manifest=read_edition(root,value["source_identity"]);source=Path(edition["source"])
        identity={"schema":PROCESS_SCHEMA,"role":"operator","product":value["product"],"workspace_id":value["workspace_id"],"pid":os.getpid(),"instance_id":str(uuid.uuid4()),"started_at":manage.now(),"installation_id":value["installation_id"],"source_identity":value["source_identity"],"directory":str(root),"workspace":value["workspace"],"application":str(source),"entry_sha256":file_identity(source/"workbench"/"app.py")["sha256"],"launcher_sha256":file_identity(Path(__file__).resolve())["sha256"],"device":str(root.stat().st_dev),"inode":str(root.stat().st_ino),"ready_file":str(ready)}
        old_stdout=sys.stdout;old_signal=signal.getsignal(signal.SIGTERM)
        def stop(signum,frame):raise KeyboardInterrupt
        signal.signal(signal.SIGTERM,stop)
        try:
            with application(root,value) as ctx:
                ws=ctx["Workspace"](value["workspace"],value["product"]);ws.validate()
                need(ws.meta["id"]==value["workspace_id"],"workspace_changed","The original workspace identity changed.")
                sys.stdout=OriginalAnnouncement(old_stdout,identity,ws.meta,ready,a.port)
                ctx["app"].serve(ws,a.port)
        finally:sys.stdout=old_stdout;signal.signal(signal.SIGTERM,old_signal)
if __name__=="__main__":
    try:main()
    except KeyboardInterrupt:pass
    except (WorkbenchError,ValueError,KeyError,TypeError,OSError) as error:
        print(json.dumps({"schema":"stellar-forge.partner-process-error.v1","code":getattr(error,"code","original_service_failed"),"message":str(error)[:2000]}),file=sys.stderr,flush=True);raise SystemExit(2)

